/* ─── Reusable animation hook ─────────────────────────────────────────────── */
function useReveal(threshold = 0.1) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setVisible(true); io.disconnect(); } },
      { threshold }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ children, delay = 0, className = "" }) {
  const [ref, visible] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(28px)",
        transition: `opacity .8s cubic-bezier(.16,1,.3,1) ${delay}s, transform .8s cubic-bezier(.16,1,.3,1) ${delay}s`,
      }}
    >
      {children}
    </div>
  );
}

/* ─── Glass surface ───────────────────────────────────────────────────────── */
function Glass({ children, className = "", style = {} }) {
  return (
    <div
      className={`rounded-3xl border border-white/80 ${className}`}
      style={{ background: "rgba(255,255,255,.72)", backdropFilter: "blur(20px)", ...style }}
    >
      {children}
    </div>
  );
}

/* ─── Section label ───────────────────────────────────────────────────────── */
function Label({ children, color = "#5BB8D4" }) {
  return (
    <span
      className="inline-block text-[10px] font-bold tracking-[.18em] uppercase text-[#46466A] pb-1.5"
      style={{ borderBottom: `2px solid ${color}` }}
    >
      {children}
    </span>
  );
}

